<?php

declare(strict_types=1);

require_once __DIR__ . '/HubBrowserOriginPolicy.php';

final class HubControlPlaneRouter
{
    private const MAX_BODY_BYTES = 16384;
    private const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}';

    public static function dispatch(string $method, string $requestUri, array $server, HubControlPlaneService $service, string $body, array $files = []): array
    {
        $requestId = self::requestId();
        $headers = ['Content-Type' => 'application/json; charset=utf-8', 'Cache-Control' => 'no-store', 'X-Content-Type-Options' => 'nosniff', 'Referrer-Policy' => 'no-referrer', 'Content-Security-Policy' => "default-src 'none'"];
        $parts = parse_url($requestUri);
        $path = is_array($parts) && is_string($parts['path'] ?? null) ? $parts['path'] : '';
        $query = is_array($parts) && is_string($parts['query'] ?? null) ? $parts['query'] : '';
        if (preg_match('/(?:^|[&])(access_token|refresh_token|token|secret|password|authorization|credential)=/i', $query)) return self::response(400, self::error('AUTHORIZATION_IN_URL', $requestId, 'Credentials are forbidden in request URLs'), $headers);
        $attachmentUpload = $method === 'POST' && preg_match('#^/api/v1/control/conversations/thread/' . self::UUID . '/attachments$#i', $path) === 1;
        $workerCandidateUpload = $method === 'POST' && preg_match('#^/api/v1/control/worker/executions/' . self::UUID . '/candidate$#i', $path) === 1;
        $workerOfficeArtifact = $method === 'POST' && preg_match('#^/api/v1/control/worker/executions/' . self::UUID . '/office-artifact$#i', $path) === 1;
        $workerProjectSource = $method === 'POST' && preg_match('#^/api/v1/control/worker/projects/' . self::UUID . '/source/[0-9a-f]{40,64}$#i', $path) === 1;
        if (!$attachmentUpload && !$workerCandidateUpload && !$workerOfficeArtifact && !$workerProjectSource && strlen($body) > self::MAX_BODY_BYTES) return self::response(413, self::error('BODY_TOO_LARGE', $requestId, 'Control-plane request is too large'), $headers);
        if ($method === 'POST' && (!$attachmentUpload && !$workerCandidateUpload && !$workerOfficeArtifact && !$workerProjectSource && (!isset($server['CONTENT_TYPE']) || !is_string($server['CONTENT_TYPE']) || stripos($server['CONTENT_TYPE'], 'application/json') !== 0))) return self::response(415, self::error('CONTENT_TYPE_REQUIRED', $requestId, 'JSON content type is required'), $headers);
        if ($attachmentUpload && (!isset($server['CONTENT_TYPE']) || !is_string($server['CONTENT_TYPE']) || stripos($server['CONTENT_TYPE'], 'multipart/form-data') !== 0)) return self::response(415, self::error('CONTENT_TYPE_REQUIRED', $requestId, 'Multipart attachment content is required'), $headers);
        if ($workerCandidateUpload && (!isset($server['CONTENT_TYPE']) || !is_string($server['CONTENT_TYPE']) || stripos($server['CONTENT_TYPE'], 'application/octet-stream') !== 0)) return self::response(415, self::error('CONTENT_TYPE_REQUIRED', $requestId, 'Binary candidate content is required'), $headers);
        if ($workerProjectSource && (!isset($server['CONTENT_TYPE']) || !is_string($server['CONTENT_TYPE']) || stripos($server['CONTENT_TYPE'], 'application/zip') !== 0)) return self::response(415, self::error('CONTENT_TYPE_REQUIRED', $requestId, 'ZIP project source content is required'), $headers);
        if ($workerOfficeArtifact && (!isset($server['CONTENT_TYPE']) || !is_string($server['CONTENT_TYPE']) || stripos($server['CONTENT_TYPE'], 'application/pdf') !== 0)) return self::response(415, self::error('CONTENT_TYPE_REQUIRED', $requestId, 'PDF artifact content is required'), $headers);
        if ($path === '/api/v1/control/session' && $method === 'POST') {
            try {
                self::sameOrigin($server);
                $payload = self::json($body);
                self::exactKeys($payload, ['appVersion', 'displayName', 'pairingCode', 'schemaVersion']);
                if (($payload['schemaVersion'] ?? null) !== 1) throw new HubControlPlaneException('Unsupported session schema', 'SCHEMA_VERSION');
                $session = $service->openSession((string) $payload['pairingCode'], (string) $payload['displayName'], (string) $payload['appVersion'], null, self::rateKey($server));
                $headers += self::sessionCookies((string) $session['sessionToken'], (string) $session['csrfToken']);
                return self::response(200, ['schemaVersion' => 1, 'authenticated' => true, 'expiresAt' => $session['expiresAt'], 'userId' => $session['userId'], 'requestId' => $requestId], $headers);
            } catch (Throwable $error) { return self::exceptionResponse($error, $requestId, $headers); }
        }
        try {
            if ($method === 'GET') {
                self::sameOriginIfBrowser($server);
                if (preg_match('#^/api/v1/control/worker/results/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->workerResults(self::bearer($server), $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/worker/projects/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->workerProjects(self::bearer($server), $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/worker/conversations/(' . self::UUID . ')/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->workerConversation(self::bearer($server), $match[1], $match[2]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/worker/workspaces/(' . self::UUID . ')/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->workerWorkspace(self::bearer($server), $match[1], $match[2]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/worker/executions/(' . self::UUID . ')/packet$#i', $path, $match) === 1) return self::response(200, $service->workerExecutionPacket(self::bearer($server), self::workerDevice($server), $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/worker/executions/(' . self::UUID . ')/workspace$#i', $path, $match) === 1) return self::downloadResponse($service->workerExecutionWorkspace(self::bearer($server), self::workerDevice($server), $match[1]), $headers);
                if (preg_match('#^/api/v1/control/worker/executions/(' . self::UUID . ')/office-packet$#i', $path, $match) === 1) return self::response(200, $service->workerOfficeExecutionPacket(self::bearer($server), self::workerDevice($server), $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/worker/executions/(' . self::UUID . ')/office-input$#i', $path, $match) === 1) return self::downloadResponse($service->workerOfficeExecutionInput(self::bearer($server), self::workerDevice($server), $match[1]), $headers);
                $sessionToken = self::cookie($server, '__Host-awh_control_session');
                if ($path === '/api/v1/control/session') return self::response(200, $service->session($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/projects') return self::response(200, $service->listProjectsForSession($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/tasks') return self::response(200, $service->listTasks($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/automations') return self::response(200, $service->automations($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/results') return self::response(200, $service->results($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/artifacts') return self::response(200, $service->artifacts($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/approvals') return self::response(200, $service->approvals($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/workers') return self::response(200, $service->workers($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/conversations') return self::response(200, $service->conversations($sessionToken, self::queryValue($query, 'projectId'), self::queryValue($query, 'q')) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/settings') return self::response(200, $service->productSettings($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/product-identity') return self::response(200, $service->productIdentityForSession($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/settings/history') return self::response(200, $service->productSettingHistory($sessionToken, (string) self::queryValue($query, 'settingKey')) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/memory') return self::response(200, $service->memory($sessionToken, self::queryValue($query, 'projectId'), self::queryValue($query, 'scope'), self::queryValue($query, 'q')) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/memory/imports') return self::response(200, $service->memoryImportReport($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/export') return self::response(200, $service->exportWorkspace($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/owner/status') return self::response(200, $service->ownerSelfServiceStatus($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/infrastructure') return self::response(200, $service->infrastructure($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/hosting/sites') return self::response(200, $service->managedSitesForSession($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/trust') return self::response(200, $service->trustCenter($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/ai') return self::response(200, $service->aiGovernanceStatus($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/provider') return self::response(200, $service->providerStatus($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/cloud') return self::response(200, $service->cloudStatus($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/cloud/revision') return self::response(200, $service->cloudRevision($sessionToken) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/provider/projects/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->providerProjectRouting($sessionToken, $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/attachments/(' . self::UUID . ')/download$#i', $path, $match) === 1) return self::downloadResponse($service->attachmentDownload($sessionToken, $match[1]), $headers);
                if (preg_match('#^/api/v1/control/artifacts/(' . self::UUID . ')/download$#i', $path, $match) === 1) return self::downloadResponse($service->artifactDownload($sessionToken, $match[1]), $headers);
                if (preg_match('#^/api/v1/control/workspaces/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->workspace($sessionToken, $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/projects/(' . self::UUID . ')/bindings$#i', $path, $match) === 1) return self::response(200, $service->projectBindings($sessionToken, $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/projects/(' . self::UUID . ')/vault$#i', $path, $match) === 1) return self::response(200, $service->projectVault($sessionToken, $match[1]) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/system/readiness') return self::response(200, $service->systemReadiness($sessionToken) + ['requestId' => $requestId], $headers);
                if ($path === '/api/v1/control/capabilities') return self::response(200, $service->capabilityStatus($sessionToken) + ['requestId' => $requestId], $headers);
                // Keep the M6 project route stable for already-packaged desktop
                // clients. M8 thread identity has an explicit `thread` segment,
                // so a project UUID can never be misread as a conversation UUID.
                if (preg_match('#^/api/v1/control/conversations/thread/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->conversationById($sessionToken, $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/conversations(?:/project)?/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->conversation($sessionToken, $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/contexts/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->currentContext($sessionToken, $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/tasks/(' . self::UUID . ')$#i', $path, $match) === 1) return self::response(200, $service->getTask($sessionToken, $match[1]) + ['requestId' => $requestId], $headers);
                if (preg_match('#^/api/v1/control/approvals/(' . self::UUID . ')$#i', $path, $match) === 1) { $all = $service->approvals($sessionToken); foreach ($all['approvals'] as $approval) if (strcasecmp((string) $approval['approvalId'], $match[1]) === 0) return self::response(200, $approval + ['requestId' => $requestId], $headers); throw new HubControlPlaneException('Approval was not found', 'APPROVAL_NOT_FOUND'); }
                return self::response(404, self::error('NOT_FOUND', $requestId, 'Control-plane route was not found'), $headers);
            }
            if ($method !== 'POST') return self::response(405, self::error('METHOD_NOT_ALLOWED', $requestId, 'Only bounded GET and POST routes are supported'), $headers + ['Allow' => 'GET, POST']);
            if (preg_match('#^/api/v1/control/conversations/thread/(' . self::UUID . ')/attachments$#i', $path, $match) === 1) { self::sameOrigin($server); return self::response(201, $service->uploadConversationAttachments(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $match[1], $files) + ['requestId' => $requestId], $headers); }
            if (preg_match('#^/api/v1/control/worker/executions/(' . self::UUID . ')/candidate$#i', $path, $match) === 1) return self::response(201, $service->acceptWorkerExecutionCandidate(self::bearer($server), self::workerDevice($server), $match[1], $files['candidate'] ?? []) + ['requestId' => $requestId], $headers);
            if (preg_match('#^/api/v1/control/worker/projects/(' . self::UUID . ')/source/([0-9a-f]{40,64})$#i', $path, $match) === 1) return self::response(201, $service->acceptWorkerProjectSource(self::bearer($server), self::workerDevice($server), $match[1], strtolower($match[2]), $files['projectSource'] ?? []) + ['requestId' => $requestId], $headers);
            if (preg_match('#^/api/v1/control/worker/executions/(' . self::UUID . ')/office-artifact$#i', $path, $match) === 1) return self::response(201, $service->acceptOfficeExecutionArtifact(self::bearer($server), self::workerDevice($server), $match[1], $files['officeArtifact'] ?? []) + ['requestId' => $requestId], $headers);
            $payload = self::json($body);
            if ($path === '/api/v1/control/projects') { self::sameOrigin($server); return self::response(201, $service->createProjectForSession(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/hosting/sites') { self::sameOrigin($server); return self::response(201, $service->createManagedSiteForSession(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if (preg_match('#^/api/v1/control/hosting/sites/(' . self::UUID . ')/(deploy|rollback|disable)$#i', $path, $match) === 1) { self::sameOrigin($server); $session=self::cookie($server,'__Host-awh_control_session'); $csrf=self::csrf($server); $result = match(strtolower($match[2])) { 'deploy'=>$service->deployManagedSiteForSession($session,$csrf,$match[1],$payload), 'rollback'=>$service->rollbackManagedSiteForSession($session,$csrf,$match[1],$payload), default=>$service->disableManagedSiteForSession($session,$csrf,$match[1],$payload) }; return self::response(200,$result+['requestId'=>$requestId],$headers); }
            if ($path === '/api/v1/control/school/documents') { self::sameOrigin($server); return self::response(201, $service->createSchoolDocument(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/project-factory') { self::sameOrigin($server); return self::response(201, $service->createProjectFactory(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/conversations/new') { self::sameOrigin($server); return self::response(201, $service->createConversation(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/conversations') { self::sameOrigin($server); return self::response(201, $service->submitConversation(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if (preg_match('#^/api/v1/control/conversations/thread/(' . self::UUID . ')$#i', $path, $match) === 1) { self::sameOrigin($server); return self::response(200, $service->updateConversation(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $match[1], $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/owner/password-reset-link') return self::response(200, $service->issueOwnerPasswordResetLink(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/contexts') { self::sameOrigin($server); return self::response(200, $service->setCurrentContext(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/settings') { self::sameOrigin($server); return self::response(200, $service->updateProductSetting(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/settings/reset') { self::sameOrigin($server); return self::response(200, $service->resetProductSetting(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/memory/create') { self::sameOrigin($server); return self::response(201, $service->createMemory(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/memory') { self::sameOrigin($server); return self::response(200, $service->updateMemory(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/provider') { self::sameOrigin($server); return self::response(200, $service->updateProviderPolicy(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/provider/credential') { self::sameOrigin($server); return self::response(200, $service->updateProviderCredential(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/cloud/credential') { self::sameOrigin($server); return self::response(200, $service->updateCloudCredential(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/cloud/tasks') { self::sameOrigin($server); return self::response(201, $service->submitCloudTask(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/provider/test') { self::sameOrigin($server); return self::response(200, $service->testProviderConnection(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/provider/project') { self::sameOrigin($server); return self::response(200, $service->updateProviderProjectRouting(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/projects/vault/ingest') { self::sameOrigin($server); return self::response(201, $service->ingestProjectVault(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/projects/vault/promote') { self::sameOrigin($server); return self::response(200, $service->promoteProjectVaultRevision(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/automations') { self::sameOrigin($server); return self::response(201, $service->createAutomation(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if (preg_match('#^/api/v1/control/automations/(' . self::UUID . ')$#i', $path, $match) === 1) { self::sameOrigin($server); return self::response(200, $service->replaceAutomation(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $match[1], $payload) + ['requestId' => $requestId], $headers); }
            if (preg_match('#^/api/v1/control/automations/(' . self::UUID . ')/enabled$#i', $path, $match) === 1) { self::sameOrigin($server); return self::response(200, $service->setAutomationEnabled(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $match[1], $payload) + ['requestId' => $requestId], $headers); }
            if (preg_match('#^/api/v1/control/automations/(' . self::UUID . ')/archive$#i', $path, $match) === 1) { self::sameOrigin($server); return self::response(200, $service->archiveAutomation(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $match[1], $payload) + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/tasks') { self::sameOrigin($server); return self::response(201, $service->submitTask(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $payload) + ['requestId' => $requestId], $headers); }
            if (preg_match('#^/api/v1/control/tasks/(' . self::UUID . ')/cancel$#i', $path, $match) === 1) { self::sameOrigin($server); self::exactKeys($payload, ['schemaVersion']); if (($payload['schemaVersion'] ?? null) !== 1) throw new HubControlPlaneException('Unsupported cancellation schema', 'SCHEMA_VERSION'); return self::response(200, $service->cancelTask(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $match[1]) + ['requestId' => $requestId], $headers); }
            if (preg_match('#^/api/v1/control/approvals/(' . self::UUID . ')/(approve|reject)$#i', $path, $match) === 1) { self::sameOrigin($server); self::exactKeys($payload, ['schemaVersion']); if (($payload['schemaVersion'] ?? null) !== 1) throw new HubControlPlaneException('Unsupported approval schema', 'SCHEMA_VERSION'); return self::response(200, $service->decideApproval(self::cookie($server, '__Host-awh_control_session'), self::csrf($server), $match[1], strtolower($match[2]) === 'approve' ? 'APPROVED' : 'REJECTED') + ['requestId' => $requestId], $headers); }
            if ($path === '/api/v1/control/workers/heartbeat') return self::response(200, $service->heartbeat(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/workers/claim') return self::response(200, $service->claim(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/worker/conversations') return self::response(201, $service->submitWorkerConversation(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/worker/projects/register') return self::response(201, $service->registerProjectFromDevice(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/worker/projects/memory') return self::response(200, $service->publishProjectMemoryFromDevice(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/worker/projects/bindings') return self::response(200, $service->registerProjectBinding(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/worker/workspaces/checkpoints') return self::response(201, $service->publishWorkspaceCheckpoint(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/worker/workspaces/leases/claim') return self::response(200, $service->claimWorkspaceLease(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/worker/workspaces/leases/renew') return self::response(200, $service->renewWorkspaceLease(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if ($path === '/api/v1/control/worker/workspaces/leases/release') return self::response(200, $service->releaseWorkspaceLease(self::bearer($server), $payload) + ['requestId' => $requestId], $headers);
            if (preg_match('#^/api/v1/control/tasks/(' . self::UUID . ')/artifact$#i', $path, $match) === 1) return self::response(201, $service->addArtifact(self::bearer($server), $match[1], $payload) + ['requestId' => $requestId], $headers);
            if (preg_match('#^/api/v1/control/tasks/(' . self::UUID . ')/update$#i', $path, $match) === 1) return self::response(200, $service->updateTask(self::bearer($server), $match[1], $payload) + ['requestId' => $requestId], $headers);
            if (preg_match('#^/api/v1/control/worker/executions/(' . self::UUID . ')/defer$#i', $path, $match) === 1) return self::response(200, $service->deferWorkerExecution(self::bearer($server), self::workerDevice($server), $match[1], $payload) + ['requestId' => $requestId], $headers);
            return self::response(404, self::error('NOT_FOUND', $requestId, 'Control-plane route was not found'), $headers);
        } catch (Throwable $error) { return self::exceptionResponse($error, $requestId, $headers); }
    }

    private static function json(string $body): array { try { $value = json_decode($body, true, 32, JSON_THROW_ON_ERROR); } catch (JsonException) { throw new HubControlPlaneException('JSON payload is invalid', 'PAYLOAD_INVALID'); } if (!is_array($value) || array_is_list($value)) throw new HubControlPlaneException('JSON object is required', 'PAYLOAD_INVALID'); return $value; }
    private static function queryValue(string $query, string $name): ?string { if ($query === '') return null; parse_str($query, $values); if (!is_array($values) || !array_key_exists($name, $values)) return null; $value = $values[$name]; if (!is_string($value) || strlen($value) > 160 || preg_match('/[\x00-\x1f\x7f]/', $value)) throw new HubControlPlaneException('Query is invalid', 'FIELD_INVALID'); return $value; }
    private static function exactKeys(array $value, array $allowed): void { $actual = array_keys($value); sort($actual); sort($allowed); if ($actual !== $allowed) throw new HubControlPlaneException('Payload contains unsupported fields', 'SCHEMA_FIELDS'); }
    private static function bearer(array $server): string { $header = $server['HTTP_AUTHORIZATION'] ?? ''; if (!is_string($header) || preg_match('/^Bearer\s+([^\s]+)$/i', $header, $match) !== 1) throw new HubControlPlaneException('Worker authentication is required', 'TOKEN_INVALID'); return $match[1]; }
    private static function workerDevice(array $server): string { $value = $server['HTTP_X_AWH_DEVICE'] ?? ''; if (!is_string($value) || preg_match('/^' . self::UUID . '$/i', $value) !== 1) throw new HubControlPlaneException('Worker device reference is invalid', 'FIELD_INVALID'); return strtolower($value); }
    private static function cookie(array $server, string $name): string { $raw = $server['HTTP_COOKIE'] ?? ''; if (!is_string($raw)) throw new HubControlPlaneException('Control session is required', 'SESSION_INVALID'); foreach (explode(';', $raw) as $part) { [$key, $value] = array_pad(explode('=', trim($part), 2), 2, ''); if ($key === $name && preg_match('/^[A-Za-z0-9_-]{32,128}$/', $value)) return $value; } throw new HubControlPlaneException('Control session is required', 'SESSION_INVALID'); }
    private static function csrf(array $server): string { $value = $server['HTTP_X_AWH_CSRF'] ?? ''; if (!is_string($value) || !preg_match('/^[A-Za-z0-9_-]{32,128}$/', $value)) throw new HubControlPlaneException('CSRF validation is required', 'CSRF_REJECTED'); return $value; }
    private static function rateKey(array $server): string { $address = isset($server['REMOTE_ADDR']) && is_string($server['REMOTE_ADDR']) && filter_var($server['REMOTE_ADDR'], FILTER_VALIDATE_IP) !== false ? $server['REMOTE_ADDR'] : 'unknown'; $agent = isset($server['HTTP_USER_AGENT']) && is_string($server['HTTP_USER_AGENT']) ? substr($server['HTTP_USER_AGENT'], 0, 160) : 'unknown'; return hash('sha256', $address . "\n" . $agent); }
    private static function sameOrigin(array $server): void { if (!HubBrowserOriginPolicy::mutationAllowed($server)) throw new HubControlPlaneException('Browser origin is not authorized', 'ORIGIN_FORBIDDEN'); }
    private static function sameOriginIfBrowser(array $server): void { if (!HubBrowserOriginPolicy::safeReadAllowed($server)) throw new HubControlPlaneException('Browser origin is not authorized', 'ORIGIN_FORBIDDEN'); }
    private static function sessionCookies(string $session, string $csrf): array { return ['Set-Cookie' => ['__Host-awh_control_session=' . $session . '; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=28800', 'awh_csrf=' . $csrf . '; Path=/; Secure; SameSite=Strict; Max-Age=28800']]; }
    private static function exceptionResponse(Throwable $error, string $requestId, array $headers): array { $code = $error instanceof HubControlPlaneException ? $error->codeName : ($error instanceof HubProjectVaultException || $error instanceof HubDurableExecutionException || $error instanceof HubCentralProjectAuthorityMigrationException ? $error->codeName : 'CONTROL_PLANE_UNAVAILABLE'); $status = match ($code) { 'ORIGIN_FORBIDDEN', 'CSRF_REJECTED', 'WORKSPACE_LEASE_FORBIDDEN', 'ATTACHMENT_FORBIDDEN', 'OWNER_FORBIDDEN', 'STEP_UP_REQUIRED', 'MEMORY_FORBIDDEN', 'PROJECT_CONTEXT_FORBIDDEN' => 403, 'SESSION_INVALID', 'SESSION_EXPIRED', 'TOKEN_INVALID' => 401, 'PROJECT_FORBIDDEN', 'TASK_FORBIDDEN' => 403, 'TASK_NOT_FOUND', 'SITE_NOT_FOUND', 'CONVERSATION_NOT_FOUND', 'AUTOMATION_NOT_FOUND', 'APPROVAL_NOT_FOUND', 'ATTACHMENT_NOT_FOUND', 'ARTIFACT_NOT_FOUND', 'MEMORY_NOT_FOUND', 'IMPORT_BATCH_NOT_FOUND', 'PROJECT_FILE_NOT_FOUND', 'PROJECT_REVISION_NOT_FOUND' => 404, 'RATE_LIMITED', 'PROVIDER_RATE_LIMITED', 'CLOUD_RATE_LIMITED' => 429, 'WORKER_NOT_READY', 'WORKER_BUSY', 'TASK_CLAIM_RACE', 'TASK_UPDATE_RACE', 'TASK_CANCEL_RACE', 'TASK_NOT_CANCELLABLE', 'APPROVAL_ALREADY_DECIDED', 'WORKSPACE_LEASE_HELD', 'SITE_SLUG_UNAVAILABLE', 'ROLLBACK_NOT_READY', 'WORKSPACE_CHECKPOINT_CONFLICT', 'WORKSPACE_CHECKPOINT_STALE', 'WORKSPACE_CHECKPOINT_REQUIRED', 'PROJECT_ID_CONFLICT', 'PROJECT_NAME_CONFLICT', 'PROJECT_REVISION_CONFLICT', 'TASK_WORKSPACE_CONFLICT', 'PROVIDER_CREDENTIAL_STATE_UNCERTAIN', 'AUTOMATION_CONFLICT', 'CLOUD_CONFLICT', 'CLOUD_LEASE_LOST', 'CLOUD_RUN_MISMATCH' => 409, 'SCHEMA_VERSION', 'PAYLOAD_INVALID', 'SCHEMA_FIELDS', 'FIELD_INVALID', 'ID_INVALID', 'GOAL_INVALID', 'IDEMPOTENCY_INVALID', 'PAIRING_CODE_INVALID', 'APPROVAL_DECISION_INVALID', 'ATTACHMENT_INVALID', 'ATTACHMENT_TYPE_FORBIDDEN', 'PROVIDER_POLICY_INVALID', 'PROVIDER_CREDENTIAL_INVALID', 'PROVIDER_AUTH_FAILED', 'PROVIDER_PERMISSION_DENIED', 'PROVIDER_MODEL_UNAVAILABLE', 'PROVIDER_REQUEST_INVALID', 'MEMORY_INVALID', 'MEMORY_SENSITIVE_EXCLUDED', 'PROJECT_ARCHIVE_INVALID', 'PROJECT_ARCHIVE_UNSAFE', 'PROJECT_CONTEXT_INVALID', 'PROJECT_VAULT_INVALID', 'EXECUTION_INVALID', 'TASK_WORKSPACE_INVALID', 'AUTOMATION_INVALID', 'HOSTING_INVALID', 'DOMAIN_BINDING_REQUIRED', 'CLOUD_TASK_INVALID', 'CLOUD_CREDENTIAL_INVALID', 'CLOUD_CHECKPOINT_INVALID', 'CLOUD_CAPABILITY_INVALID', 'CLOUD_REQUEST_INVALID', 'CLOUD_ARTIFACT_INVALID', 'CLOUD_FINDINGS_INVALID' => 400, 'PROJECT_ARCHIVE_TOO_LARGE' => 413, 'PAIRING_REPLAY', 'APPROVAL_EXPIRED' => 409, 'CONTROL_SCHEMA_NOT_READY', 'ASSISTANT_SCHEMA_NOT_READY', 'WORKSPACE_SCHEMA_NOT_READY', 'UNIFIED_WORKSPACE_SCHEMA_NOT_READY', 'FINAL_PRODUCT_SCHEMA_NOT_READY', 'FOUNDING_MEMORY_SCHEMA_NOT_READY', 'SELF_SERVICE_SCHEMA_NOT_READY', 'CENTRAL_PROJECT_AUTHORITY_NOT_READY', 'PROJECT_VAULT_UNAVAILABLE', 'TASK_WORKSPACE_UNAVAILABLE', 'ARTIFACT_STORAGE_UNAVAILABLE', 'ARTIFACT_STORAGE_FAILED', 'ATTACHMENT_STORAGE_UNAVAILABLE', 'ATTACHMENT_STORAGE_FAILED', 'DATABASE_UNAVAILABLE', 'PROJECT_CREATE_FAILED', 'MEMORY_CREATE_FAILED', 'PROVIDER_CREDENTIAL_FAILED', 'PROVIDER_CREDENTIAL_STORE_FAILED', 'PROVIDER_UNAVAILABLE', 'PROVIDER_QUOTA_EXHAUSTED', 'PROVIDER_FAILED', 'PROVIDER_CREDENTIAL_STORE_INVALID', 'PROVIDER_CREDENTIAL_UNAVAILABLE', 'PROVIDER_TEST_FAILED', 'EXECUTION_CLAIM_FAILED', 'AUTOMATION_SCHEMA_NOT_READY', 'ACCOUNT_HOSTING_SCHEMA_NOT_READY', 'HOSTING_CREATE_FAILED', 'HOSTING_DEPLOY_FAILED', 'HOSTING_DISABLE_FAILED', 'HOSTING_ROLLBACK_FAILED', 'HOSTING_CAPACITY_FULL', 'PROJECT_SOURCE_NOT_READY', 'CLOUD_NOT_READY', 'CLOUD_NOT_CONFIGURED', 'CLOUD_HTTP_UNAVAILABLE', 'CLOUD_UNAVAILABLE', 'CLOUD_WORKFLOW_NOT_FOUND', 'CLOUD_ARTIFACT_MISSING', 'CLOUD_TASK_CREATE_FAILED' => 503, default => 400 }; $body = self::error($code, $requestId, self::safeMessage($code)); $diagnostic = $error instanceof HubControlPlaneException ? self::safeDiagnostic($error->details) : []; if ($diagnostic !== []) $body['diagnostic'] = $diagnostic; return self::response($status, $body, $headers); }
    private static function safeMessage(string $code): string { return match ($code) { 'ORIGIN_FORBIDDEN' => 'This AWH surface is not authorized', 'CSRF_REJECTED' => 'The request could not be verified', 'SESSION_INVALID', 'SESSION_EXPIRED' => 'Your AWH session has expired', 'STEP_UP_REQUIRED' => 'This high-risk action requires privileged confirmation', 'TOKEN_INVALID' => 'Worker authentication failed', 'PROJECT_FORBIDDEN' => 'This project is not available to the current device', 'PROJECT_VAULT_EMPTY' => 'This project has not been stored in AWH Vault yet', 'PROJECT_REVISION_CONFLICT' => 'Project content changed before this version could be promoted', 'PROJECT_ARCHIVE_TOO_LARGE' => 'Project archive is larger than the safe limit', 'PROJECT_ARCHIVE_UNSAFE' => 'Project archive contains unsafe paths or unsupported content', 'TASK_NOT_FOUND' => 'Task was not found', 'MEMORY_FORBIDDEN' => 'This memory is not available to the current account', 'MEMORY_SENSITIVE_EXCLUDED' => 'Sensitive material cannot be stored as ordinary memory', 'CONTROL_SCHEMA_NOT_READY', 'CENTRAL_PROJECT_AUTHORITY_NOT_READY' => 'AWH control plane is not activated', 'PAIRING_REPLAY' => 'This connection code was already used', 'PROVIDER_AUTH_FAILED' => 'OpenAI rejected the configured API key', 'PROVIDER_PERMISSION_DENIED' => 'OpenAI denied this account or project request', 'PROVIDER_QUOTA_EXHAUSTED' => 'OpenAI quota or billing capacity is not available', 'PROVIDER_MODEL_UNAVAILABLE' => 'The configured AI model is unavailable', 'PROVIDER_REQUEST_INVALID' => 'The configured provider rejected the AWH request', 'PROVIDER_RATE_LIMITED' => 'The AI provider is temporarily rate limited', 'PROVIDER_UNAVAILABLE' => 'The AI provider is temporarily unavailable', 'PROJECT_SOURCE_NOT_READY' => 'AWH ยังไม่พบ Source ที่พร้อม Deploy และกำลังรอ Project Context', 'HOSTING_CAPACITY_FULL' => 'พื้นที่ public route ของ VPS เต็ม กรุณาตรวจ Hosting capacity', 'SITE_SLUG_UNAVAILABLE' => 'ชื่อย่อเว็บไซต์นี้ถูกใช้แล้ว', 'ROLLBACK_NOT_READY' => 'เว็บไซต์นี้ยังไม่มีรุ่นก่อนหน้าที่ตรวจสอบแล้ว', 'CLOUD_NOT_READY' => 'AWH Cloud is not activated yet', 'CLOUD_NOT_CONFIGURED' => 'AWH Cloud needs an Owner credential before use', 'CLOUD_RATE_LIMITED' => 'AWH Cloud is temporarily rate limited', 'CLOUD_UNAVAILABLE', 'CLOUD_HTTP_UNAVAILABLE' => 'AWH Cloud is temporarily unavailable', 'CLOUD_RUN_MISMATCH' => 'AWH Cloud could not verify the exact remote run', default => 'AWH could not complete the request' }; }

    /** @param array<string,mixed> $details @return array<string,mixed> */
    private static function safeDiagnostic(array $details): array { $out = []; foreach (['provider','operation','category','httpStatusClass','providerType','providerCode','model'] as $key) if (is_string($details[$key] ?? null) && preg_match('/^[A-Za-z0-9._:-]{1,100}$/', (string) $details[$key]) === 1) $out[$key] = (string) $details[$key]; if (is_int($details['httpStatus'] ?? null) && $details['httpStatus'] >= 100 && $details['httpStatus'] <= 599) $out['httpStatus'] = $details['httpStatus']; if (is_int($details['transportCode'] ?? null) && $details['transportCode'] > 0 && $details['transportCode'] < 1000) $out['transportCode'] = $details['transportCode']; if (is_bool($details['retryable'] ?? null)) $out['retryable'] = $details['retryable']; return $out; }
    private static function requestId(): string { $bytes = random_bytes(16); $bytes[6] = chr((ord($bytes[6]) & 15) | 64); $bytes[8] = chr((ord($bytes[8]) & 63) | 128); return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4)); }
    private static function response(int $status, array $body, array $headers): array { return ['status' => $status, 'headers' => $headers, 'body' => json_encode($body, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . "\n"]; }
    private static function downloadResponse(array $download, array $headers): array { return ['status' => 200, 'headers' => ['Content-Type' => (string) $download['mimeType'], 'Content-Length' => (string) $download['sizeBytes'], 'Content-Disposition' => 'attachment; filename="' . rawurlencode((string) $download['name']) . '"', 'Cache-Control' => 'private, no-store', 'X-Content-Type-Options' => 'nosniff', 'Referrer-Policy' => 'no-referrer'], 'body' => '', 'streamPath' => (string) $download['path']]; }
    private static function error(string $code, string $requestId, string $message): array { return ['schemaVersion' => 1, 'error' => 'ERROR', 'code' => $code, 'requestId' => $requestId, 'message' => $message]; }
}
